html,body { background:#0f172a !important; margin:0; padding:0; }
.app { width:100%; box-sizing:border-box; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; }
.ag-theme-alpine { --ag-header-background-color:#0f172a; --ag-header-foreground-color:#FFFFFF; --ag-odd-row-background-color:#0f172a; --ag-background-color:#1E293B; --ag-row-hover-color:#1E293B; --ag-selected-row-background-color:#1E293B; --ag-foreground-color:#FFFFFF; --ag-border-color:#1E293B; --ag-font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; --ag-font-size:14px; --ag-row-height:44px; --ag-header-height:48px; border-radius:6px; border:1px solid #1E293B; overflow:hidden; }
.ag-theme-alpine .ag-row-odd { background-color:#0f172a !important; }
.ag-theme-alpine .ag-row-even { background-color:#1E293B !important; }
.ag-theme-alpine .ag-row-hover { background-color:rgba(255,255,255,0.05) !important; }
.ag-theme-alpine .ag-cell { border-right:1px solid rgba(255,255,255,0.04); line-height:44px; }
.ag-theme-alpine .ag-header { font-weight:600; background:#0f172a; border-bottom:2px solid #1E293B; }
.ag-theme-alpine .ag-header-cell-text { color:#FFFFFF; }
.ag-theme-alpine .ag-paging-panel { background:#0f172a; color:#FFFFFF; border-top:2px solid #1E293B; }
.ag-theme-alpine .ag-paging-panel * { color:#FFFFFF !important; }
.detail-link { color:#60a5fa; cursor:pointer; font-weight:600; }
.ag-cell:hover .detail-link { text-decoration:underline; }
.pill { display:inline-flex; align-items:center; gap:7px; }
.dot { width:8px; height:8px; border-radius:50%; display:inline-block; }
::-webkit-scrollbar { width:10px; height:10px; background:#0f172a; }
::-webkit-scrollbar-thumb { background:#1E293B; border-radius:4px; border:2px solid #0f172a; }
* { scrollbar-color:#1E293B #0f172a; scrollbar-width:thin; }

